package main

import (
	"context"
	"log"
	"time"

	"github.com/sumup/sumup-go"
	"github.com/sumup/sumup-go/nullable"
)

func main() {
	ctx := context.Background()
	client := sumup.NewClient()

	result, err := client.Checkouts.Create(ctx, sumup.CheckoutsCreateParams{
		Amount:            10.1,
		CheckoutReference: "f00a8f74-b05d-4605-bd73-2a901bae5802",
		Currency:          "EUR",
		Description:       ptr("Purchase"),
		MerchantCode:      "MH4H92C7",
		RedirectURL:       ptr("https://sumup.com"),
		ValidUntil:        nullable.Value(mustParseTime("2020-02-29T10:56:56+00:00")),
	})
	if err != nil {
		log.Fatal(err)
	}

	log.Printf("%+v", result)
}

func ptr[T any](value T) *T {
	return &value
}

func mustParseTime(value string) time.Time {
	parsed, err := time.Parse(time.RFC3339, value)
	if err != nil {
		panic(err)
	}
	return parsed
}

